156			return nil, err
157		}
158	
159		memo, err := s.Store.GetMemo(ctx, &store.FindMemo{ID: &ms.MemoID})
160		if err != nil {
161			return nil, status.Errorf(codes.Internal, "failed to get memo")
162		}
163		// Treat archived or missing memos the same as an invalid token — no information leakage.
164		if memo == nil || memo.RowStatus == store.Archived {
165			return nil, status.Errorf(codes.NotFound, "not found")
166		}
167	
168		reactions, err := s.Store.ListReactions(ctx, &store.FindReaction{
169			ContentID: stringPointer(fmt.Sprintf("%s%s", MemoNamePrefix, memo.UID)),
170		})
171		if err != nil {
172			return nil, status.Errorf(codes.Internal, "failed to list reactions")
173		}
174	
175		attachments, err := s.Store.ListAttachments(ctx, &store.FindAttachment{MemoID: &memo.ID})
176		if err != nil {
177			return nil, status.Errorf(codes.Internal, "failed to list attachments")
178		}
179		relations, err := s.batchConvertMemoRelations(ctx, []*store.Memo{memo}, true)
180		if err != nil {
181			return nil, status.Errorf(codes.Internal, "failed to load memo relations")
182		}
183	
184		memoMessage, err := s.convertMemoFromStore(ctx, memo, reactions, attachments, relations[memo.ID])
185		if err != nil {
186			if stderrors.Is(err, errMemoCreatorNotFound) {
187				return nil, status.Errorf(codes.NotFound, "not found")
188			}
189			return nil, errors.Wrap(err, "failed to convert memo")
190		}
191		return memoMessage, nil
192	}
